package org.sleepwell.app;

import android.content.*;
import android.net.Uri;
import android.os.*;
import java.io.*;
import java.lang.ref.WeakReference;
import java.nio.charset.CharacterCodingException;
import java.util.*;
import java.util.concurrent.*;
import java.util.concurrent.atomic.*;

/** Retained, explicit read/review/append. Process loss never automatically reads or appends again. */
final class SleepCsvJob implements AutoCloseable {
    enum Phase {EMPTY,CHOOSING,READING,REVIEW,APPENDING,DONE,ERROR}
    static final class State {final Phase phase;final SleepCsvImport.Review review;final String message;State(Phase phase,SleepCsvImport.Review review,String message){this.phase=phase;this.review=review;this.message=message;}boolean busy(){return phase==Phase.CHOOSING||phase==Phase.READING||phase==Phase.APPENDING;}}
    interface Observer {void changed(State value);}
    private static final Semaphore READ=new Semaphore(1);private static final Executor CANCEL=new ThreadPoolExecutor(0,1,10,TimeUnit.SECONDS,new ArrayBlockingQueue<>(2),r->new Thread(r,"sleep-csv-cancel"),new ThreadPoolExecutor.DiscardPolicy());
    final Context app;final Records.Factory records;final ExecutorService worker=Executors.newSingleThreadExecutor();final Handler main=new Handler(Looper.getMainLooper());final AtomicInteger gate=new AtomicInteger();final AtomicReference<CancellationSignal> signal=new AtomicReference<>();final AtomicReference<ParcelFileDescriptor> descriptor=new AtomicReference<>();private WeakReference<Observer> observer=new WeakReference<>(null);private volatile boolean closed;private volatile State state;int request=30000+ThreadLocalRandom.current().nextInt(10000);
    SleepCsvJob(Context context,boolean interrupted){app=context.getApplicationContext();records=Records.factory;state=new State(Phase.EMPTY,null,interrupted?"The earlier import was interrupted. Nothing resumes automatically. Choose the CSV again; already imported IDs will be identified during review.":"");}
    State state(){return state;}void observe(Observer target){observer=new WeakReference<>(target);target.changed(state);}void detach(Observer target){if(observer.get()==target)observer.clear();}private void publish(State value){if(closed)return;state=value;Observer target=observer.get();if(target!=null)target.changed(value);}
    boolean choose(){if(closed||state.busy())return false;request=request>=60000?30000:request+1;publish(new State(Phase.CHOOSING,state.review,"Choose the original sleep-export.csv document."));return true;}
    void cancelChoice(){if(state.phase==Phase.CHOOSING){request=request>=60000?30000:request+1;publish(new State(state.review==null?Phase.EMPTY:Phase.REVIEW,state.review,"Document choice cancelled. No periods were added."));}}
    private boolean active(){return !closed&&gate.get()==0;}
    void read(Uri uri){if(closed||state.phase!=Phase.CHOOSING)return;if(uri==null||!"content".equals(uri.getScheme())||uri.getAuthority()==null){publish(new State(Phase.ERROR,null,"Choose a CSV through Android Files."));return;}long admission=BackupRuntime.generation();gate.set(0);publish(new State(Phase.READING,null,"Reading and validating the CSV…"));worker.execute(()->{boolean admitted=false;try{
            BackupRuntime.requireIdle(app,admission);if(!READ.tryAcquire())throw new IllegalStateException("An earlier CSV reader is still closing. Try again shortly.");admitted=true;byte[] bytes;CancellationSignal cancel=new CancellationSignal();signal.set(cancel);try{NightAudioArchive.active(this::active);ParcelFileDescriptor file=app.getContentResolver().openFileDescriptor(uri,"r",cancel);if(file==null)throw new IOException("CSV document unavailable.");descriptor.set(file);try(InputStream input=new ParcelFileDescriptor.AutoCloseInputStream(file);ByteArrayOutputStream output=new ByteArrayOutputStream()){byte[] buffer=new byte[8192];int empty=0;while(true){NightAudioArchive.active(this::active);BackupRuntime.requireIdle(app,admission);int n=input.read(buffer);if(n<0)break;if(n==0){if(++empty>16)throw new IOException("Document provider returned no data.");continue;}empty=0;if(output.size()+n>SleepCsvFormat.MAX_FILE)throw new IllegalArgumentException("Choose a CSV no larger than 4 MiB.");output.write(buffer,0,n);}bytes=output.toByteArray();}finally{descriptor.compareAndSet(file,null);}}finally{signal.compareAndSet(cancel,null);}
            SleepCsvImport.Review review;try(Store store=records.open(app)){review=SleepCsvImport.prepare(app,store,bytes,this::active,admission);}NightAudioArchive.active(this::active);main.post(()->{if(active())publish(new State(Phase.REVIEW,review,"Review new periods and conflicts. Existing records remain unchanged until Append."));else publish(new State(Phase.ERROR,null,"Import cancelled before commit."));});
        }catch(Exception error){String message=notice(error,false);main.post(()->publish(new State(Phase.ERROR,null,message)));}finally{if(admitted)READ.release();}});}
    void append(Set<String> selected){if(closed||state.phase!=Phase.REVIEW||state.review==null)return;SleepCsvImport.Review review=state.review;Set<String> choices=Set.copyOf(selected);if(choices.isEmpty())return;gate.set(0);publish(new State(Phase.APPENDING,review,"Adding reviewed historical periods…"));worker.execute(()->{try(Store store=records.open(app)){int added=SleepCsvImport.append(app,store,review,choices,this::active,new SleepCsvImport.Commit(){public void begin(){if(!gate.compareAndSet(0,2))throw new CancellationException();}public void committed(){gate.set(3);}});main.post(()->publish(new State(Phase.DONE,null,"Added "+added+" historical periods and their original CSV evidence. Existing records and conflicting IDs were kept. No alarms, measurements or stage estimates were created.")));}catch(Exception error){String message=notice(error,gate.get()>=2);main.post(()->publish(new State(Phase.ERROR,null,message)));}});}
    boolean cancel(){if(state.phase==Phase.CHOOSING){cancelChoice();return true;}if(state.phase!=Phase.READING&&state.phase!=Phase.APPENDING)return true;if(!gate.compareAndSet(0,1))return gate.get()==1;CancellationSignal cancel=signal.get();ParcelFileDescriptor file=descriptor.get();CANCEL.execute(()->{if(cancel!=null)try{cancel.cancel();}catch(RuntimeException ignored){}if(file!=null)try{file.close();}catch(IOException ignored){}});return true;}
    private static String notice(Exception error,boolean uncertain){if(uncertain)return "The import result could not be confirmed. Reopen history before retrying. Source IDs prevent silently replaying the same records.";if(error instanceof CharacterCodingException)return "This file is not valid UTF-8. No periods were added.";if(error instanceof CancellationException||error instanceof InterruptedIOException)return "Import cancelled before commit. No periods were added.";if(error instanceof IllegalArgumentException||error instanceof IllegalStateException||error instanceof IOException){String message=error.getMessage();if(message!=null&&message.length()<420)return message;}return "The CSV import could not finish. Existing records were not overwritten or deleted.";}
    public void close(){if(closed)return;cancel();closed=true;observer.clear();worker.shutdown();}
}
